import java.util.*;
import java.io.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;

    // Reads the next whitespace-separated token from stdin
    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
        return st.nextToken();
    }

    static int nextInt() throws IOException { return Integer.parseInt(next()); }

    static void reverse(int[] a, int l, int r) {
        while (l < r) {
            int t = a[l]; a[l] = a[r]; a[r] = t;
            l++; r--;
        }
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long kk = Long.parseLong(next());
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nextInt();
        int k = (int) (kk % n);               // N rotations = no change
        reverse(a, 0, n - 1);                 // last k elements jump to the front (backwards)
        reverse(a, 0, k - 1);                 // fix order of the front block
        reverse(a, k, n - 1);                 // fix order of the back block
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(a[i]);
        }
        System.out.println(sb);
    }
}

